schemaSql:
create table if not exists tareg5_settings (
  id bigint generated by default as identity primary key,
  usd_rate numeric not null default 600,
  updated_at timestamptz default now()
);

create table if not exists tareg5_delivery_areas (
  id bigint generated by default as identity primary key,
  name text not null unique,
  delivery_fee numeric not null default 0,
  created_at timestamptz default now()
);

create table if not exists tareg5_products (
  id bigint generated by default as identity primary key,
  name text not null,
  category text not null,
  price_usd numeric not null,
  stock_quantity integer not null default 0,
  image_url text,
  is_visible boolean not null default true,
  created_at timestamptz default now()
);

create table if not exists tareg5_customers (
  id uuid primary key default auth.uid(),
  full_name text not null,
  phone text not null,
  email text not null,
  created_at timestamptz default now()
);

create table if not exists tareg5_orders (
  id bigint generated by default as identity primary key,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  customer_name text not null,
  customer_phone text not null,
  area_name text not null,
  delivery_fee numeric not null,
  delivery_type text not null, -- 'delivery' or 'pickup'
  detailed_address text,
  total_amount numeric not null,
  status text not null default 'جديد', -- 'جديد', 'قيد التجهيز', 'في الطريق', 'تم'
  created_at timestamptz default now()
);

create table if not exists tareg5_order_items (
  id bigint generated by default as identity primary key,
  order_id bigint not null references tareg5_orders(id) on delete cascade,
  product_id bigint references tareg5_products(id) on delete set null,
  product_name text not null,
  quantity integer not null,
  unit_price_sdg numeric not null,
  total_price_sdg numeric not null,
  created_at timestamptz default now()
);

create table if not exists tareg5_purchases (
  id bigint generated by default as identity primary key,
  supplier_name text not null,
  purchase_date date not null,
  amount_usd numeric not null,
  payment_status text not null, -- 'مدفوع بالكامل', 'آجل (غير مدفوع)'
  invoice_image_url text,
  created_at timestamptz default now()
);

-- Enable RLS
alter table tareg5_settings enable row level security;
alter table tareg5_delivery_areas enable row level security;
alter table tareg5_products enable row level security;
alter table tareg5_customers enable row level security;
alter table tareg5_orders enable row level security;
alter table tareg5_order_items enable row level security;
alter table tareg5_purchases enable row level security;

-- Policies
drop policy if exists "settings_select" on tareg5_settings;
create policy "settings_select" on tareg5_settings for select to authenticated using (true);

drop policy if exists "settings_modify" on tareg5_settings;
create policy "settings_modify" on tareg5_settings for all to authenticated using (public.tareg5_is_admin()) with check (public.tareg5_is_admin());

drop policy if exists "delivery_areas_select" on tareg5_delivery_areas;
create policy "delivery_areas_select" on tareg5_delivery_areas for select to authenticated using (true);

drop policy if exists "delivery_areas_modify" on tareg5_delivery_areas;
create policy "delivery_areas_modify" on tareg5_delivery_areas for all to authenticated using (public.tareg5_is_admin()) with check (public.tareg5_is_admin());

drop policy if exists "products_select" on tareg5_products;
create policy "products_select" on tareg5_products for select to authenticated using (true);

drop policy if exists "products_modify" on tareg5_products;
create policy "products_modify" on tareg5_products for all to authenticated using (public.tareg5_is_admin()) with check (public.tareg5_is_admin());

drop policy if exists "customers_all" on tareg5_customers;
create policy "customers_all" on tareg5_customers for all to authenticated using (id = auth.uid() or public.tareg5_is_admin()) with check (id = auth.uid() or public.tareg5_is_admin());

drop policy if exists "orders_select" on tareg5_orders;
create policy "orders_select" on tareg5_orders for select to authenticated using (customer_id = auth.uid() or public.tareg5_is_admin());

drop policy if exists "orders_insert" on tareg5_orders;
create policy "orders_insert" on tareg5_orders for insert to authenticated with check (customer_id = auth.uid());

drop policy if exists "orders_update" on tareg5_orders;
create policy "orders_update" on tareg5_orders for update to authenticated using (customer_id = auth.uid() or public.tareg5_is_admin()) with check (customer_id = auth.uid() or public.tareg5_is_admin());

drop policy if exists "order_items_select" on tareg5_order_items;
create policy "order_items_select" on tareg5_order_items for select to authenticated using (
  exists (select 1 from tareg5_orders o where o.id = order_id and (o.customer_id = auth.uid() or public.tareg5_is_admin()))
);

drop policy if exists "order_items_insert" on tareg5_order_items;
create policy "order_items_insert" on tareg5_order_items for insert to authenticated with check (
  exists (select 1 from tareg5_orders o where o.id = order_id and o.customer_id = auth.uid())
);

drop policy if exists "purchases_all" on tareg5_purchases;
create policy "purchases_all" on tareg5_purchases for all to authenticated using (public.tareg5_is_admin()) with check (public.tareg5_is_admin());

